// Simpan data terakhir di context (untuk GET /api/suhu)
var d = msg.payload;
d.received = new Date().toISOString();
flow.set('lastSensor', d);

var th = flow.get('threshold');
if (th === undefined) th = 30;

// Simpan ke SQLite
var db = global.get('db');
if (db) {
    try {
        db.prepare('INSERT INTO sensor (suhu, kelembaban, ts, received) VALUES (?, ?, ?, ?)')
          .run(d.suhu, d.kelembaban, d.timestamp ?? null, d.received);
    } catch (e) { node.error('Insert DB gagal: ' + e.message); }
}

// Output 1: broadcast WebSocket
var ws = {payload: {type: 'sensor', data: d, threshold: th}};
// Output 2: notifikasi jika suhu melewati batas
var alert = null;
if (d.suhu > th) {
    alert = {topic: 'iot/alert', payload: {type: 'alert', message: 'Suhu ' + d.suhu + ' C melewati batas ' + th + ' C', suhu: d.suhu, threshold: th, time: d.received}};
}
return [ws, alert];

// Buka database SQLite bawaan Node (node:sqlite) dan buat tabel
try {
    const { DatabaseSync } = global.get('sqlite');
    const db = new DatabaseSync('C:/Users/LENOVO/.node-red/iot.db');
    db.exec('CREATE TABLE IF NOT EXISTS sensor (id INTEGER PRIMARY KEY AUTOINCREMENT, suhu REAL, kelembaban REAL, ts TEXT, received TEXT)');
    global.set('db', db);
    node.status({fill: 'green', shape: 'dot', text: 'DB siap'});
} catch (e) {
    node.status({fill: 'red', shape: 'ring', text: 'DB gagal'});
    node.error('Init DB gagal: ' + e.message + ' (cek functionGlobalContext di settings.js)');
}
return null;

var H = {'Access-Control-Allow-Origin': '*'};
if (msg.req.headers['x-api-key'] !== 'iot-secret-123') {
    msg.statusCode = 401; msg.headers = H;
    msg.payload = {status: 'error', message: 'Unauthorized: X-API-Key salah atau tidak ada'};
    return msg;
}
var data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
var th = flow.get('threshold');
if (th === undefined) th = 30;
msg.statusCode = 200;
msg.headers = H;
msg.payload = {status: 'success', data: data, threshold: th, server_time: new Date().toISOString()};
return msg;

var H = {'Access-Control-Allow-Origin': '*'};
if (msg.req.headers['x-api-key'] !== 'iot-secret-123') {
    msg.statusCode = 401; msg.headers = H;
    msg.payload = {status: 'error', message: 'Unauthorized: X-API-Key salah atau tidak ada'};
    return msg;
}
var db = global.get('db');
msg.headers = H;
if (!db) {
    msg.statusCode = 503;
    msg.payload = {status: 'error', message: 'Database belum siap'};
    return msg;
}
var rows = db.prepare('SELECT suhu, kelembaban, received FROM sensor ORDER BY id DESC LIMIT 50').all()
             .map(r => ({suhu: r.suhu, kelembaban: r.kelembaban, received: r.received}))
             .reverse(); // urut lama -> baru
msg.statusCode = 200;
msg.payload = {status: 'success', count: rows.length, data: rows};
return msg;

var H = {'Access-Control-Allow-Origin': '*'};
if (msg.req.headers['x-api-key'] !== 'iot-secret-123') {
    msg.statusCode = 401; msg.headers = H;
    msg.payload = {status: 'error', message: 'Unauthorized: X-API-Key salah atau tidak ada'};
    return [msg, null];
}
var body = msg.payload;
if (!body || !body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'device dan action wajib diisi'};
    msg.headers = H;
    return [msg, null];
}
node.send([null, {payload: body, topic: 'iot/kontrol'}]);
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Perintah terkirim', sent: body};
msg.headers = H;
return [msg, null];

var H = {'Access-Control-Allow-Origin': '*'};
if (msg.req.headers['x-api-key'] !== 'iot-secret-123') {
    msg.statusCode = 401; msg.headers = H;
    msg.payload = {status: 'error', message: 'Unauthorized: X-API-Key salah atau tidak ada'};
    return msg;
}
var max = msg.payload ? msg.payload.max : undefined;
msg.headers = H;
if (typeof max !== 'number' || !isFinite(max)) {
    msg.statusCode = 400;
    msg.payload = {status: 'error', message: 'Body harus JSON: {"max": <angka>}'};
    return msg;
}
flow.set('threshold', max);
msg.statusCode = 200;
msg.payload = {status: 'success', message: 'Batas suhu diperbarui', threshold: max};
return msg;

msg.statusCode = 204;
msg.payload = '';
msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
return msg;
